import { test, expect } from '@playwright/test';

test.describe('CSV Import Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully import records from a valid CSV file', async ({ page }) => {
    // Setup: intercept the API call
    await page.route('**/api/records/import', (route) => {
      route.continue();
    });

    // Setup: create a valid CSV file
    const csvContent = 'id,name,email\n1,John Doe,john@example.com\n2,Jane Smith,jane@example.com';
    const csvFile = await page.evaluate((content) => {
      const blob = new Blob([content], { type: 'text/csv' });
      return URL.createObjectURL(blob);
    }, csvContent);

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload CSV');
    await expect(fileInput).toBeVisible();

    // Set the file input value
    await fileInput.setInputFiles(csvFile);

    // Get and click the import button using getByRole
    const importButton = page.getByRole('button', { name: /import records/i });
    await expect(importButton).toBeVisible();
    await importButton.click();

    // Wait for the import process to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/records/import') && response.status() === 200
    );

    // Verify success message appears
    const successMessage = page.getByText(/import successful/i);
    await expect(successMessage).toBeVisible();

    // Verify records are displayed
    const recordList = page.getByRole('region', { name: /records/i });
    await expect(recordList).toBeVisible();

    const recordItems = page.locator('[data-testid="record-item"]');
    const count = await recordItems.count();
    expect(count).toBe(2);

    // Verify imported data is visible
    const recordNames = page.locator('[data-testid="record-name"]');
    const names = await recordNames.allTextContents();
    expect(names).toContain('John Doe');
    expect(names).toContain('Jane Smith');
  });

  test('should display error message when uploading an invalid CSV file', async ({ page }) => {
    // Setup: intercept the API call
    await page.route('**/api/records/import', (route) => {
      route.abort('failed');
    });

    // Setup: create an invalid CSV file (missing closing quotes)
    const invalidCsvContent = 'id,name,email\n1,"John Doe\n2,"Jane Smith,jane@example.com';
    const csvFile = await page.evaluate((content) => {
      const blob = new Blob([content], { type: 'text/csv' });
      return URL.createObjectURL(blob);
    }, invalidCsvContent);

    // Get the file input using getByLabel
    const fileInput = page.getByLabel('Upload CSV');
    await expect(fileInput).toBeVisible();

    // Set the invalid file input
    await fileInput.setInputFiles(csvFile);

    // Get and click the import button using getByRole
    const importButton = page.getByRole('button', { name: /import records/i });
    await expect(importButton).toBeVisible();
    await importButton.click();

    // Wait for the error response
    await page.waitForResponse(response => 
      response.url().includes('/api/records/import') && response.status() === 400
    );

    // Verify error message appears
    const errorMessage = page.getByText(/invalid csv format/i);
    await expect(errorMessage).toBeVisible();

    // Verify no records are displayed
    const recordList = page.getByRole('region', { name: /records/i });
    const recordItems = page.locator('[data-testid="record-item"]');
    const count = await recordItems.count();
    expect(count).toBe(0);

    // Verify the file input is still visible for retry
    await expect(fileInput).toBeVisible();
  });
});
